    titel: 'BWP-H-05 — der Kessel speist hinter dem Puffer ein',
    text: 'In BWP-H-05 hängt der Pufferspeicher allein am Wärmepumpenzweig und wird ausschließlich von der Wärmepumpe beladen. Der Kessel speist über einen motorischen 3-Wege-Mischer mit Beimischstrecke und Vorlauftemperaturfühler in den gemeinsamen Heizungsvorlauf stromab des Puffers ein; damit bleibt die Kesselwärme aus dem Puffervolumen heraus. Der Kessel hat ein eigenes Membran-Ausdehnungsgefäß und einen eigenen Ladekreis mit Pumpe und Rückschlagklappe zum oberen Wärmeübertrager des Trinkwassererwärmers, während die Wärmepumpe den unteren bedient. Beide Heizkreise sind gemischt ausgeführt. Zur Kesselauslegung gilt: bivalent-alternativ und bivalent-teilparallel verlangen, dass der Kessel die gesamte Heizlast des Hauses deckt, bivalent-parallel, dass die Summe aus Wärmepumpe und zweitem Wärmeerzeuger sie deckt.',
