/** Recherchestand der drei Berichte, aus denen dieser Korpus stammt. */
export const KORPUS_STAND = '2026-08';

/**
 * Zahl der Einträge je Korpus.
 *
 * Nützlich für die Anzeige („45 Sätze aus Normen und Recht") und als
 * schneller Selbsttest: fehlt ein Korpus in der Ausgabe, ist beim Anfügen
 * neuer Einträge eine Zuordnung verrutscht.
 */
export function korpusUmfang(): Record<string, number> {
  const zaehler: Record<string, number> = {};
  for (const eintrag of WISSEN_KORPUS) {
    zaehler[eintrag.korpus] = (zaehler[eintrag.korpus] ?? 0) + 1;
  }
  return zaehler;
}
